function parseCounts(form){
  form=String(form).replace(/[\s·×*]/g,'.');
  var i=0, n=form.length;
  function readFactor(){
    var map={};
    while(i<n){
      var c=form[i];
      if(c==='('){ i++; var g=readFactor();
        var num=1; if(i<n && /[0-9]/.test(form[i])){num=0;while(i<n&&/[0-9]/.test(form[i])){num=num*10+(form[i].charCodeAt(0)-48);i++;}}
        for(var k in g) map[k]=(map[k]||0)+g[k]*num;
        continue;
      }
      if(c===')'){ i++; break; }
      if(c==='.'){ i++;
        var mult=1; if(i<n && /[0-9]/.test(form[i])){mult=0;while(i<n&&/[0-9]/.test(form[i])){mult=mult*10+(form[i].charCodeAt(0)-48);i++;}}
        var rest=readFactor();
        for(var k in rest) map[k]=(map[k]||0)+rest[k]*mult;
        break;
      }
      if(/[A-Z]/.test(c)){
        var sym=c; i++;
        while(i<n && /[a-z]/.test(form[i])){ sym+=form[i]; i++; }
        var cnt=1; if(i<n && /[0-9]/.test(form[i])){cnt=0;while(i<n&&/[0-9]/.test(form[i])){cnt=cnt*10+(form[i].charCodeAt(0)-48);i++;}}
        map[sym]=(map[sym]||0)+cnt;
        continue;
      }
      i++;
    }
    return map;
  }
  return readFactor();
}

function parseEquation(eq){
  var sides=eq.split(/\s*(?:->|→|=)\s*/); if(sides.length!==2) return null;
  function side(s){ return s.split('+').map(function(p){ p=p.trim(); var m=p.match(/^(\d+)?\s*([A-Za-z0-9().]+)$/);
    if(!m) return null; return {formula:m[2], coeff:m[1]?parseInt(m[1],10):1}; }).filter(Boolean); }
  return {reactants:side(sides[0]), products:side(sides[1])};
}
function limiting(eq, amounts, target){
  // amounts: {formula: molesAvailable}; target: product formula
  var p=parseEquation(eq); if(!p) return {error:"方程式格式错误"};
  var tgt=null; for(var i=0;i<p.products.length;i++) if(p.products[i].formula===target) tgt=p.products[i];
  if(!tgt) return {error:"目标产物 "+target+" 不在方程式中"};
  var lim=null, theo=Infinity;
  for(var i=0;i<p.reactants.length;i++){ var r=p.reactants[i];
    var avail=amounts[r.formula]; if(avail==null) return {error:"缺少反应物 "+r.formula+" 的量"};
    var possible=avail*tgt.coeff/r.coeff;
    if(possible<theo){ theo=possible; lim=r.formula; }
  }
  return {ok:true, limiting:lim, theoretical:theo};
}
function percentYield(actual, theoretical){ if(theoretical<=0) return null; return actual/theoretical*100; }
var EXPORTS={parseEquation:parseEquation, limiting:limiting, percentYield:percentYield};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.YieldForgePure = EXPORTS; }
